# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

Names = List[Student]


def _name_key(student: Student):
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _full(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _render_row(number: int, group: Names) -> str:
    names = [_full(one) for one in group]
    return f"Row {number}: " + " | ".join(names)


def _check(students: Names, seats: int) -> None:
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _chunks(items: Names, size: int) -> List[Names]:
    return [items[at:at + size]
            for at in range(0, len(items), size)]


def seating_rows(students: Names, seats: int) -> List[str]:
    """One line of text per row, sorted by last name."""
    _check(students, seats)
    ordered = sorted(students, key=_name_key)
    groups = _chunks(ordered, seats)
    return [_render_row(num, grp)
            for num, grp in enumerate(groups, start=1)]

